import { stringifyTree, containsUpdates, parseSdkTargetFromMetadata, } from '@mintlify/common';
import { upgradeToDocsConfig } from '@mintlify/validation';
import { outputFile } from 'fs-extra';
import { join } from 'path';
import { loadSdkReferenceSource, updateDocsConfigFile, writeSdkFrontmatterPages, } from './docsConfig/index.js';
import { updateMintConfigFile } from './mintConfig/index.js';
import { scanPageMetadata } from './read/read-page-metadata.js';
import { readPageContents, readSnippetsV2Contents } from './read/readContent.js';
import { readPackageNames } from './read/readPackageNames.js';
import { resolveImportsAndWriteFiles } from './resolveImportsAndWriteFiles.js';
import { updateFavicons } from './updateFavicons.js';
import { updateGeneratedDocsNav, updateGeneratedNav } from './updateGeneratedNav.js';
import { writeAsyncApiFiles } from './write/writeAsyncApiFiles.js';
import { writeFiles, writeFile } from './write/writeFiles.js';
import { writeOpenApiData } from './write/writeOpenApiData.js';
import { writeRssFiles } from './write/writeRssFiles.js';
const expandRssCandidates = (rssCandidateFilenames, contentFilenames, fileImportsMap, pageScans) => {
    const carriers = new Set();
    for (const [filename, scan] of pageScans) {
        if (scan.rssCandidate) {
            carriers.add(filename.toLowerCase());
        }
    }
    let changed = carriers.size > 0;
    while (changed) {
        changed = false;
        for (const [filename, imports] of fileImportsMap) {
            if (carriers.has(filename))
                continue;
            for (const imported of imports) {
                if (carriers.has(imported)) {
                    carriers.add(filename);
                    changed = true;
                    break;
                }
            }
        }
    }
    const candidates = new Set(rssCandidateFilenames);
    for (const filename of contentFilenames) {
        if (carriers.has(filename.toLowerCase())) {
            candidates.add(filename);
        }
    }
    return [...candidates];
};
const filterToImportClosure = (snippetV2Filenames, rootFilenames, fileImportsMap) => {
    const needed = new Set();
    const stack = rootFilenames.map((filename) => filename.toLowerCase());
    let current = stack.pop();
    while (current !== undefined) {
        for (const imported of fileImportsMap.get(current) ?? []) {
            if (!needed.has(imported)) {
                needed.add(imported);
                stack.push(imported);
            }
        }
        current = stack.pop();
    }
    return snippetV2Filenames.filter((filename) => needed.has(filename.toLowerCase()));
};
export const update = async ({ contentDirectoryPath, staticFilenames, openApiFiles, asyncApiFiles, contentFilenames, snippets, snippetV2Filenames, docsConfigPath, localSchema, groups, mintIgnore, disableOpenApi, disablePrefetch, strict, skipStaticFiles, invalidSpecFiles, allowSourceRefs, lazyPages, pageScans, fileImportsMap, overlayRegistry, nativePackages, }) => {
    const mintConfigResult = await updateMintConfigFile(contentDirectoryPath, openApiFiles, localSchema, strict, invalidSpecFiles);
    // we used the original mint config without openapi pages injected
    // because we will do it in `updateDocsConfigFile`, this will avoid duplicated openapi pages
    const docsConfig = mintConfigResult != null ? upgradeToDocsConfig(mintConfigResult.originalMintConfig) : undefined;
    const { docsConfig: newDocsConfig, pagesAcc, newOpenApiFiles, newAsyncApiFiles, customLanguages, inheritedSdkBySlug, pageMetadataBySlug, } = await updateDocsConfigFile({
        contentDirectoryPath,
        openApiFiles,
        asyncApiFiles,
        docsConfig: docsConfigPath ? undefined : docsConfig,
        localSchema,
        disableOpenApi,
        strict,
        invalidSpecFiles,
        allowSourceRefs,
        overlayRegistry,
        pageScans,
    });
    let contentFilenamesToParse = contentFilenames;
    if (lazyPages) {
        const { rssCandidateFilenames } = await scanPageMetadata({
            contentDirectoryPath,
            openApiFiles: newOpenApiFiles,
            asyncApiFiles: newAsyncApiFiles,
            contentFilenames,
            pagesAcc,
            pageScans,
        });
        contentFilenamesToParse =
            fileImportsMap && pageScans
                ? expandRssCandidates(rssCandidateFilenames, contentFilenames, fileImportsMap, pageScans)
                : rssCandidateFilenames;
        // Composed SDK pages must be parsed even in lazy builds so
        // writeSdkFrontmatterPages layers the generated body over processed
        // (import-resolved) author content instead of the raw source file.
        const sdkComposeFilenames = contentFilenames.filter((filename) => {
            const slug = filename.replace(/^\//, '').replace(/\.mdx?$/, '');
            const metadata = pageMetadataBySlug[slug];
            if (!metadata)
                return false;
            return (parseSdkTargetFromMetadata({ sdk: metadata.sdk }, inheritedSdkBySlug[slug]) !== undefined);
        });
        contentFilenamesToParse = [...new Set([...contentFilenamesToParse, ...sdkComposeFilenames])];
    }
    const pagePromises = readPageContents({
        contentDirectoryPath,
        openApiFiles: newOpenApiFiles,
        asyncApiFiles: newAsyncApiFiles,
        contentFilenames: contentFilenamesToParse,
        pagesAcc,
    });
    const snippetV2FilenamesToParse = lazyPages && fileImportsMap
        ? filterToImportClosure(snippetV2Filenames, contentFilenamesToParse, fileImportsMap)
        : snippetV2Filenames;
    const snippetV2Promises = readSnippetsV2Contents(contentDirectoryPath, snippetV2FilenamesToParse, newDocsConfig.variables ?? undefined);
    const [snippetV2Contents, { mdxFilesWithNoImports, filesWithImports }] = await Promise.all([
        snippetV2Promises,
        pagePromises,
    ]);
    // Filter pages with rss: true in frontmatter OR pages that contain Update components
    const rssPages = mdxFilesWithNoImports.filter((page) => page.metadata.rss === true || containsUpdates(page.tree));
    // Also include RSS pages that have imports (e.g., changelog entries as separate snippet files)
    // For these, we need to extract the snippets using the importMap and include the component names
    // so they can be properly resolved on the server side
    const rssPagesWithImports = filesWithImports
        .filter((file) => {
        // Check if the file has rss: true metadata
        if (file.metadata?.rss === true) {
            return true;
        }
        // Check if the file itself contains Update components
        if (containsUpdates(file.tree)) {
            return true;
        }
        // Check if any of the imported snippets contain Update components
        const importedSnippets = Object.keys(file.importMap).map((importPath) => snippetV2Contents.find((s) => s.filename === importPath));
        return importedSnippets.some((snippet) => snippet && containsUpdates(snippet.tree));
    })
        .map((file) => {
        // Extract snippets referenced by this page using its importMap
        // Map component names (import specifiers) to snippets for proper injection
        const referencedSnippets = [];
        for (const [importPath, importSpecifiers] of Object.entries(file.importMap)) {
            const snippet = snippetV2Contents.find((s) => s.filename === importPath);
            if (snippet) {
                // Get all the import names (component names) for this snippet
                const importNames = importSpecifiers.map((spec) => spec.name);
                referencedSnippets.push({
                    ...snippet,
                    importNames,
                });
            }
        }
        return {
            targetPath: join('src', '_props', file.filename),
            sourcePath: join(contentDirectoryPath, file.filename),
            tree: file.tree,
            metadata: file.metadata,
            snippets: referencedSnippets,
        };
    });
    const allRssPages = [...rssPages, ...rssPagesWithImports];
    const writeDevGroupsPromise = groups
        ? outputFile('src/_props/dev-groups.json', JSON.stringify({ groups }, null, 2), { flag: 'w' })
        : Promise.resolve();
    const writeDevFlagsPromise = disablePrefetch
        ? outputFile('src/_props/dev-flags.json', JSON.stringify({ disablePrefetch }, null, 2), {
            flag: 'w',
        })
        : Promise.resolve();
    const writeMintIgnorePromise = mintIgnore && mintIgnore.length > 0
        ? outputFile('src/_props/mint-ignore.json', JSON.stringify(mintIgnore, null, 2), {
            flag: 'w',
        })
        : Promise.resolve();
    const packageNames = nativePackages && newDocsConfig.packages !== undefined
        ? await readPackageNames(contentDirectoryPath)
        : undefined;
    await Promise.all([
        writeDevGroupsPromise,
        writeDevFlagsPromise,
        writeMintIgnorePromise,
        resolveImportsAndWriteFiles({
            openApiFiles: newOpenApiFiles,
            asyncApiFiles: newAsyncApiFiles,
            pagesAcc,
            snippetsV2: snippetV2Contents,
            filesWithImports,
            packageNames,
        }),
        writeFile(customLanguages, 'src/_props/customLanguages.json'),
        writeOpenApiData(newOpenApiFiles),
        writeAsyncApiFiles(newAsyncApiFiles),
        writeRssFiles(newDocsConfig, allRssPages, contentDirectoryPath, snippetV2Contents),
        updateFavicons(newDocsConfig, contentDirectoryPath),
        ...writeMdxFilesWithNoImports(mdxFilesWithNoImports),
        ...writeFiles(contentDirectoryPath, 'public', [
            ...(skipStaticFiles ? [] : staticFilenames),
            ...snippets,
        ]),
    ]);
    await writeSdkFrontmatterPages({
        contentDirectoryPath,
        inheritedSdkBySlug,
        pageMetadataBySlug,
        loadReference: (config) => loadSdkReferenceSource(config, contentDirectoryPath),
    });
    await updateGeneratedDocsNav(pagesAcc, newDocsConfig.navigation);
    if (mintConfigResult?.mintConfig) {
        await updateGeneratedNav(pagesAcc, mintConfigResult.mintConfig.navigation);
    }
    return newDocsConfig;
};
export const writeMdxFilesWithNoImports = (mdxFilesWithNoImports) => {
    return mdxFilesWithNoImports.map(async (response) => {
        const { targetPath, tree } = response;
        await outputFile(targetPath, stringifyTree(tree), {
            flag: 'w',
        });
    });
};
export * from './mintConfig/index.js';
export * from './docsConfig/index.js';
export * from './ConfigUpdater.js';
